.colosseum-run{max-width:680px;margin:0 auto;color:#253b39}.kicker{font-size:10px!important;letter-spacing:.15em;color:#8a6d36!important;font-weight:700}.colosseum-run h3{font:500 32px/1.2 Georgia,serif;margin:12px 0 22px}.colosseum-run p{font-size:13px;line-height:1.8;color:#5c716b}.score{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:20px;border:1px solid #d3ddd2;border-radius:10px;background:#edf2e9;margin-bottom:25px}.score>strong{font:32px Georgia,serif;color:#287366}.score small,.score>span{font:12px Arial}.colosseum-run .reward{color:#8a6d36;font-weight:700}.start-wave{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;min-height:50px;padding:13px 18px;border:1px solid #287366;border-radius:8px;background:#287366;color:white;font-weight:700;cursor:pointer;margin:24px 0 15px}.start-wave:disabled{opacity:.6}.start-wave:focus-visible{outline:3px solid #8a6d36;outline-offset:3px}.colosseum-run .hint{font-size:11px}.final-team{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:22px}.final-team>div{display:flex;align-items:center;flex-direction:column;border:1px solid #d3ddd2;border-radius:9px;padding:10px;background:#fcfcf8;min-width:0}.final-team img{width:72px;height:72px;object-fit:contain;image-rendering:pixelated}.final-team strong{font-size:12px;overflow-wrap:anywhere}.final-team span{font-size:10px;color:#5c716b;margin:6px 0}@media(max-width:420px){.colosseum-run h3{font-size:25px}.score{padding:16px}.score>strong{font-size:26px}.colosseum-run p{font-size:12px}.final-team{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
